const INJURY_STORE='fighteye-injuries-v1';
const injuryBytes=value=>new TextEncoder().encode(value);
async function injuryKey(passphrase,salt){
 const seed=await crypto.subtle.importKey('raw',injuryBytes(passphrase),'PBKDF2',false,['deriveKey']);
 return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:250000,hash:'SHA-256'},seed,{name:'AES-GCM',length:256},false,['encrypt','decrypt']);
}
function b64(bytes){return btoa(String.fromCharCode(...bytes));}
function unb64(value){return Uint8Array.from(atob(value),c=>c.charCodeAt(0));}
async function saveInjuries(){
 if(!state.injuryKey)return;
 const iv=crypto.getRandomValues(new Uint8Array(12));
 const encrypted=await crypto.subtle.encrypt({name:'AES-GCM',iv},state.injuryKey,injuryBytes(JSON.stringify(state.injuries)));
 const previous=JSON.parse(localStorage.getItem(INJURY_STORE));
 localStorage.setItem(INJURY_STORE,JSON.stringify({version:1,salt:previous.salt,iv:b64(iv),data:b64(new Uint8Array(encrypted))}));
}
async function openInjuryVault(passphrase){
 if(!globalThis.crypto?.subtle)throw new Error('Secure browser connection required');
 const stored=localStorage.getItem(INJURY_STORE);
 if(!stored){
  const salt=crypto.getRandomValues(new Uint8Array(16));
  const key=await injuryKey(passphrase,salt);
  localStorage.setItem(INJURY_STORE,JSON.stringify({version:1,salt:b64(salt)}));
  state.injuries=[];state.injuryKey=key;await saveInjuries();return;
 }
 const record=JSON.parse(stored);
 if(record.version!==1||!record.salt||!record.iv||!record.data)throw new Error('Injury record cannot be opened');
 const key=await injuryKey(passphrase,unb64(record.salt));
 const plain=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(record.iv)},key,unb64(record.data));
 const entries=JSON.parse(new TextDecoder().decode(plain));
 if(!Array.isArray(entries))throw new Error('Injury record format is invalid');
 state.injuries=entries;state.injuryKey=key;
}
