function visibleWeights(id){const rows=athleteWeights(id);if(state.weightRange==='all')return rows;const from=new Date();from.setDate(from.getDate()-Number(state.weightRange));const start=from.toLocaleDateString('en-CA',{timeZone:'Europe/London'});return rows.filter(r=>r.date>=start)}
function validateWeightBackup(data){if(data?.schema!=='fighteye-weight-v1'||!Array.isArray(data.records)||data.records.length>5000||typeof data.athlete?.name!=='string')throw new Error('This is not a FightEye weight backup.');const seen=new Set();return data.records.map(r=>{const date=String(r.date||''),kg=Number(r.kg),source=r.source;if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(kg)||kg<10||kg>500||!['Manual','Apple Health','Apple Health export'].includes(source)||seen.has(date))throw new Error('Weight backup contains an invalid or duplicate entry.');seen.add(date);return{date,kg:Math.round(kg*10)/10,source}})}
