  if(payload.complete===true&&/^\d{4}-\d{2}-\d{2}$/.test(payload.windowStart||''))for(const [date,row] of byDate)if(row.source==='Apple Health'&&date>=payload.windowStart&&date<=new Date().toLocaleDateString('en-CA',{timeZone:'Europe/London'})&&!seen.has(date))byDate.delete(date);
